#!/usr/bin/env python3
"""Generate all 96 primitive instructions and 23 equality tests."""
from pathlib import Path

import round30_1980_linear_radix_certificate as certificate
from round24_26_1980_schedule_tables import generate


if __name__ == "__main__":
    generate(certificate, 96, "96")
    output = (Path(__file__).resolve().parent.parent / "1980"
              / "jones1980_theorem5_96_schedule.tex")
    text = output.read_text(encoding="utf-8")
    text = text.replace("Generated by round24_26_1980_schedule_tables.py",
                        "Generated by round30_1980_schedule_table.py")
    text = text.replace("The twenty-two free equality tests are",
                        "The twenty-three free equality tests are")
    output.write_text(text, encoding="utf-8", newline="\n")
